(function(root){'use strict';const C=root.Critters,{Game,WEAPONS}=C,E=root.WormEconomy,{HEROES,SHOP_WEAPONS}=E;
for(const w of SHOP_WEAPONS){const index=WEAPONS.length;WEAPONS.push({...w,shop:true});w.index=index;}
const hero=id=>HEROES.find(h=>h.id===id)||HEROES[0];C.hero=hero;
const next=Game.prototype.nextTurn;Game.prototype.nextTurn=function(){next.call(this);this.stats.teamTurns??=[0,0];this.stats.teamTurns[this.team]++;const u=this.active;if(!u)return;const h=hero(u.character);this.fuel=h.fuel||100;if(u.chilled){this.fuel*=.5;u.chilled=false;}if(h.regen&&u.hp>0){const amount=Math.min(h.regen,(u.maxHP||100)-u.hp);u.hp+=amount;if(amount)this.emit('heal',{id:u.id,amount});}};
Game.prototype.weaponLock=function(i=this.weapon){const w=WEAPONS[i];if(!w)return '무기를 찾을 수 없습니다.';if(this.ammo[this.team][i]===0)return this.options.unlocked?.includes(i)?'남은 탄약이 없습니다.':w.shop?'상점에서 구매 후 사용 가능':'스테이지 클리어로 해금';const ownTurns=this.stats.teamTurns?.[this.team]||Math.ceil(this.turn/2);if(w.minTurn&&ownTurns<w.minTurn)return '내 팀 '+w.minTurn+'번째 차례부터 · 현재 '+ownTurns;if(w.lastOnly&&this.alive(this.team).length!==1)return '아군이 1마리 남았을 때 사용 가능';return '';};
const select=Game.prototype.select;Game.prototype.select=function(i){const reason=this.weaponLock(i);if(reason){this.emit('message',{text:reason});return false;}return select.call(this,i);};
const create=C.createBattle;C.createBattle=function(options={}){let account={party:['scout','scout','scout'],weapons:[]};if(root.PCWallet)try{account=root.PCWallet.read();}catch{}else{if(options.party)account.party=options.party;if(options.shopWeapons)account.weapons=options.shopWeapons;}const unlocked=[...(options.unlocked||[0,1,2,3]),...SHOP_WEAPONS.filter(w=>account.weapons.includes(w.id)).map(w=>w.index)];const g=create({...options,unlocked:[...new Set(unlocked)],party:[...account.party],matchId:options.newMatchId||root.crypto?.randomUUID?.()||Date.now()+'-'+Math.random().toString(36).slice(2)});
for(const u of g.units){const h=hero(u.team===0||g.options.mode==='local'?account.party[u.id%3]:'scout');u.character=h.id;u.maxHP=u.team===1&&g.options.mode==='ai'?Math.max(h.hp,u.hp):h.hp;u.attack=h.attack;u.guardCharges=h.guard||0;u.skin=h.color;u.skinShade=h.shade;if(u.team===0||g.options.mode==='local')u.hp=h.hp;if(h.id!=='scout')u.name=h.name;}
if(g.options.mode==='ai')for(const w of SHOP_WEAPONS)g.ammo[1][w.index]=0;g.stats.teamTurns=[0,0];g.stats.teamTurns[g.team]=1;g.fuel=hero(g.active.character).fuel||100;g.stats.facts={weapons:{},rope:0,batHits:0};return g;};
const emit=Game.prototype.emit;Game.prototype.emit=function(type,data={}){if(this.stats&&this.team===0){this.stats.facts??={weapons:{},rope:0,batHits:0};const f=this.stats.facts;if(type==='fire'||type==='batSwing'){const id=type==='batSwing'?'bat':WEAPONS[data.weapon]?.id;if(id)f.weapons[id]=(f.weapons[id]||0)+1;if(type==='batSwing'&&data.hit!==null)f.batHits++;}if(type==='ropeAttach')f.rope++;}return emit.call(this,type,data);};
// Every impact carries its original owner; reflected/self damage remains consistent.
for(const method of ['explode','blast']){const original=Game.prototype[method];Game.prototype[method]=function(p,...args){const before=this._impact;this._impact={owner:p.owner,scale:p.damageScale??1,weapon:p.weapon};try{return original.call(this,p,...args);}finally{this._impact=before;}};}
const damage=Game.prototype.damage;Game.prototype.damage=function(u,amount,sourceTeam,kind='blast'){const ctx=this._impact||(kind==='bat'?{owner:this.activeId,scale:1,weapon:C.BAT}:this._directOwner!==undefined?{owner:this._directOwner,scale:1,weapon:this.weapon}:null),owner=ctx&&this.units[ctx.owner],w=ctx&&WEAPONS[ctx.weapon];if(owner&&kind!=='water'&&kind!=='fall')amount*= (owner.attack||1)*(ctx.scale??1);const enemy=sourceTeam!==undefined&&sourceTeam!==u.team;
if(enemy&&u.guardCharges>0&&kind!=='water'&&kind!=='fall'){u.guardCharges--;this.emit('guard',{id:u.id,x:u.x,y:u.y});return;}const hp=u.hp;damage.call(this,u,amount,sourceTeam,kind);const dealt=Math.max(0,hp-u.hp);if(enemy&&dealt&&w?.kind==='frost')u.chilled=true;if(enemy&&dealt&&w?.kind==='leech'&&owner?.hp>0){const used=owner.leechRecovered||0,heal=Math.min(20-used,dealt*.25,(owner.maxHP||100)-owner.hp);if(heal>0){owner.hp+=Math.floor(heal);owner.leechRecovered=used+heal;this.emit('heal',{id:owner.id,amount:Math.floor(heal)});}}};
const fire=Game.prototype.fire;Game.prototype.fire=function(angle=this.angle,power=this.power,internal=false){const reason=this.weaponLock();if(reason){this.emit('message',{text:reason});return false;}const owner=this.active,id=this.weapon;owner.leechRecovered=0;this._directOwner=owner.id;let ok;try{ok=fire.call(this,angle,power,internal);}finally{this._directOwner=undefined;}if(ok&&owner.character==='twin'&&[0,1,2].includes(id)&&this.projectile){const main=this.projectile;main.damageScale=.65;const a=(angle+4)*Math.PI/180,second={...main,x:main.x-Math.cos(a)*8,y:main.y+Math.sin(a)*8,vx:Math.cos(a)*power*8.1,vy:-Math.sin(a)*power*8.1,age:0,trail:[],damageScale:.65};this.pendingVolley={projectile:second,delay:.22};this.emit('doubleShot',{id:owner.id});}return ok;};
const step=Game.prototype.step;Game.prototype.step=function(dt=C.STEP){if(!this.paused&&this.pendingVolley){const v=this.pendingVolley;v.delay-=dt;if(this.phase==='ended'||this.units[v.projectile.owner]?.hp<=0)this.pendingVolley=null;else if(v.delay<=0){this.salvos??=[];this.salvos.push(v.projectile);this.pendingVolley=null;this.emit('volley',{weapon:v.projectile.weapon,id:v.projectile.owner});}}return step.call(this,dt);};
// Shop restrictions apply to AI planning as well as player selection.
const ai=Game.prototype.aiShoot;Game.prototype.aiShoot=function(){const blocked=[];for(let i=0;i<WEAPONS.length;i++)if(this.weaponLock(i)&&this.ammo[this.team][i]!==0){blocked.push([i,this.ammo[this.team][i]]);this.ammo[this.team][i]=0;}try{return ai.call(this);}finally{for(const [i,n]of blocked)this.ammo[this.team][i]=n;}};
const restore=Game.restore;Game.restore=function(d){const g=restore(d);if(g){for(const u of g.units){u.maxHP??=100;u.attack??=1;u.character??='scout';u.guardCharges??=0;}g.stats.teamTurns??=[Math.ceil(g.turn/2),Math.floor(g.turn/2)];g.stats.facts??={weapons:{},rope:0,batHits:0};}return g;};
C.battleReport=g=>({id:g.options.matchId||'legacy:'+g.options.seed+':'+g.options.stage+':'+g.turn,mode:g.options.mode,stage:g.options.stage,winner:g.winner,survivors:g.alive(0).length,damage:g.stats.damage[0],turns:g.turn,weapons:g.stats.facts?.weapons||{},rope:g.stats.facts?.rope||0,batHits:g.stats.facts?.batHits||0});
if(typeof module!=='undefined')module.exports=C;
})(globalThis);
